package com.bank.cap.service;

import com.bank.cap.model.Node;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

// CP: consistency over availability. If it cannot reach a quorum, it REFUSES.
public class BalanceService {
    private static final Logger log = Logger.getLogger(BalanceService.class.getName());
    private final List<Node> replicas;
    private BigDecimal balance = new BigDecimal("1000000.00");
    public BalanceService(List<Node> replicas) { this.replicas = replicas; }

    public void debit(BigDecimal amount) {
        long reachable = replicas.stream().filter(n -> n.reachable).count();
        boolean quorum = reachable > replicas.size() / 2;
        if (!quorum) {
            // Partition: cannot confirm consistency → refuse (choose C over A).
            throw new IllegalStateException("CP: refusing debit — cannot reach quorum (partition)");
        }
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amount);
        log.info(() -> "CP debit ok, balance=" + balance);
    }
    public BigDecimal getBalance() { return balance; }
}
