package com.bank.cap.service;

import com.bank.cap.model.Node;
import java.util.List;
import java.util.logging.Logger;

// AP: availability over consistency. During a partition it returns STALE data, never errors.
public class FeedService {
    private static final Logger log = Logger.getLogger(FeedService.class.getName());
    private final List<Node> replicas;
    private String lastKnownFeed = "Rajesh: transfer Rs.50000 (as of last sync)";
    public FeedService(List<Node> replicas) { this.replicas = replicas; }

    public String getFeed() {
        boolean anyReachable = replicas.stream().anyMatch(n -> n.reachable);
        if (!anyReachable) {
            log.warning("AP: all replicas unreachable, serving last-known (possibly stale) feed");
        }
        return lastKnownFeed; // always returns something — stays available
    }
}
