package com.bank.cap;

import com.bank.cap.model.Node;
import com.bank.cap.service.BalanceService;
import com.bank.cap.service.FeedService;
import java.math.BigDecimal;
import java.util.List;

public class CapApplication {
    public static void main(String[] args) {
        Node a = new Node("dc-east"), b = new Node("dc-west");
        BalanceService balance = new BalanceService(List.of(a, b));
        FeedService feed = new FeedService(List.of(a, b));

        System.out.println("-- Healthy network --");
        balance.debit(new BigDecimal("50000")); // CP ok
        System.out.println("Feed: " + feed.getFeed());

        System.out.println("-- Partition: dc-west unreachable --");
        b.reachable = false;
        try { balance.debit(new BigDecimal("50000")); }
        catch (Exception e) { System.out.println("Balance (CP): " + e.getMessage()); }
        System.out.println("Feed (AP): " + feed.getFeed()); // still serves
    }
}
